<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])]);session_start();}
define('ROOT_PATH',dirname(__DIR__));define('DATA_PATH',ROOT_PATH.'/data');define('UPLOAD_PATH',ROOT_PATH.'/uploads/projects');foreach([DATA_PATH,UPLOAD_PATH] as $d)if(!is_dir($d))@mkdir($d,0775,true);
function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}function slugify(string $v):string{$v=strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/','-',$v),'-'));return $v?:'item-'.time();}function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function verify_csrf():void{if(!isset($_POST['csrf'])||!hash_equals($_SESSION['csrf']??'',(string)$_POST['csrf'])){http_response_code(419);exit('Invalid request token.');}}function is_admin():bool{return !empty($_SESSION['admin']);}function require_admin():void{if(!is_admin()){header('Location:'.site_url('/admin/'));exit;}}
function base_path():string{$docRoot=isset($_SERVER['DOCUMENT_ROOT'])?realpath((string)$_SERVER['DOCUMENT_ROOT']):false;$root=realpath(ROOT_PATH);if($docRoot&&$root){$docRoot=str_replace('\\','/',$docRoot);$root=str_replace('\\','/',$root);if(str_starts_with(strtolower($root),strtolower($docRoot))){$relative=trim(substr($root,strlen($docRoot)),'/');return $relative===''?'':'/'.$relative;}}$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/'));$dir=rtrim(dirname($script),'/');if(str_ends_with($dir,'/admin'))$dir=substr($dir,0,-6);return $dir==='/'?'':$dir;}function site_url(string $path=''):string{$base=base_path();$path='/'.ltrim($path,'/');return ($base?:'').$path;}function asset_url(string $path):string{return site_url($path).'?v=20261002-4';}
function database_config():array{$defaults=['host'=>'127.0.0.1','port'=>3306,'database'=>'','username'=>'','password'=>'','charset'=>'utf8mb4'];$file=ROOT_PATH.'/config/database.php';$config=is_file($file)?require $file:[];return array_merge($defaults,is_array($config)?$config:[]);}function db():?PDO{static $pdo=false;if($pdo!==false)return $pdo?:null;$c=database_config();if(empty($c['database'])){$pdo=null;return null;}try{$pdo=new PDO('mysql:host='.$c['host'].';port='.(int)$c['port'].';dbname='.$c['database'].';charset='.$c['charset'],(string)$c['username'],(string)$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);db_schema($pdo);return $pdo;}catch(Throwable $e){error_log('Database connection failed: '.$e->getMessage());$pdo=null;return null;}}
function db_schema(PDO $p):void{$sql=["CREATE TABLE IF NOT EXISTS site_store(store_key VARCHAR(100) PRIMARY KEY,payload LONGTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS site_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value LONGTEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS pages(id VARCHAR(32) PRIMARY KEY,slug VARCHAR(160) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,eyebrow VARCHAR(255),hero_text TEXT,content LONGTEXT,cta_title VARCHAR(255),cta_text TEXT,cta_label VARCHAR(120),cta_url VARCHAR(500),seo_title VARCHAR(255),seo_description TEXT,sort_order INT DEFAULT 0,visible TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS navigation_tabs(id VARCHAR(100) PRIMARY KEY,label VARCHAR(120) NOT NULL,url VARCHAR(500),page_slug VARCHAR(160),visible TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 50,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS services(id VARCHAR(100) PRIMARY KEY,name VARCHAR(255) NOT NULL,description TEXT,sort_order INT DEFAULT 0,visible TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS projects(id VARCHAR(32) PRIMARY KEY,slug VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,location VARCHAR(255),category VARCHAR(120),status VARCHAR(100),description LONGTEXT,featured TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS project_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id VARCHAR(32) NOT NULL,image_url VARCHAR(700) NOT NULL,alt_text VARCHAR(255),sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(project_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS seo_settings(page_key VARCHAR(160) PRIMARY KEY,title VARCHAR(255),description TEXT,keywords TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS quote_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255),phone VARCHAR(80),project_type VARCHAR(160),location VARCHAR(255),message LONGTEXT,status VARCHAR(40) DEFAULT 'new',submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"];foreach($sql as $q)$p->exec($q);}
function legacy_read(string $file,array $fallback=[]):array{$path=DATA_PATH.'/'.$file;if(!is_file($path))return $fallback;$a=json_decode((string)file_get_contents($path),true);return is_array($a)?$a:$fallback;}
function read_json(string $file,array $fallback=[]):array{$key=pathinfo($file,PATHINFO_FILENAME);$p=db();if(!$p)return legacy_read($file,$fallback);try{if($key==='home'){$s=$p->prepare('SELECT setting_value FROM site_settings WHERE setting_key=?');$s->execute(['home']);$v=$s->fetchColumn();if($v!==false)return json_decode($v,true)?:$fallback;}if($key==='services'){$r=$p->query('SELECT id,name,description,sort_order AS sort,visible FROM services ORDER BY sort_order,id')->fetchAll();if($r)return $r;}if($key==='tabs'){$r=$p->query('SELECT id,label,url,page_slug,visible,sort_order AS sort FROM navigation_tabs ORDER BY sort_order,id')->fetchAll();if($r)return $r;}if($key==='pages'){$r=$p->query('SELECT * FROM pages ORDER BY sort_order,title')->fetchAll();if($r)return $r;}if($key==='projects'){$r=$p->query('SELECT * FROM projects ORDER BY created_at')->fetchAll();if($r){$q=$p->prepare('SELECT image_url FROM project_images WHERE project_id=? ORDER BY sort_order,id');foreach($r as &$x){$q->execute([$x['id']]);$x['images']=$q->fetchAll(PDO::FETCH_COLUMN);$x['featured']=(bool)$x['featured'];}unset($x);return $r;}}if($key==='seo'){$out=[];foreach($p->query('SELECT * FROM seo_settings')->fetchAll() as $x)$out[$x['page_key']]=['title'=>$x['title'],'description'=>$x['description'],'keywords'=>$x['keywords']];if($out)return $out;}if($key==='quotes')return $p->query('SELECT *,submitted_at AS created_at FROM quote_submissions ORDER BY submitted_at DESC')->fetchAll();if($key==='admins'){$s=$p->query("SHOW TABLES LIKE 'admins'");if($s->fetchColumn()){$r=$p->query('SELECT username,password_hash AS password FROM admins')->fetchAll();if($r)return $r;}}$s=$p->prepare('SELECT payload FROM site_store WHERE store_key=?');$s->execute([$key]);$v=$s->fetchColumn();if($v!==false)return json_decode($v,true)?:$fallback;$legacy=legacy_read($file,[]);if($legacy){write_json($file,$legacy);return $legacy;}}catch(Throwable $e){error_log('DB read failed '.$key.': '.$e->getMessage());}return $fallback;}
function write_json(string $file,array $data):bool{$key=pathinfo($file,PATHINFO_FILENAME);$p=db();if(!$p)return false;try{$p->beginTransaction();if($key==='home'){$s=$p->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute(['home',json_encode($data,JSON_UNESCAPED_SLASHES)]);}elseif($key==='services'){$p->exec('DELETE FROM services');$s=$p->prepare('INSERT INTO services(id,name,description,sort_order,visible) VALUES(?,?,?,?,?)');foreach($data as $i=>$x)$s->execute([$x['id']??slugify($x['name']??'service'),$x['name']??'', $x['description']??'',(int)($x['sort']??$i*10),isset($x['visible'])?(int)(bool)$x['visible']:1]);}elseif($key==='tabs'){$p->exec('DELETE FROM navigation_tabs');$s=$p->prepare('INSERT INTO navigation_tabs(id,label,url,page_slug,visible,sort_order) VALUES(?,?,?,?,?,?)');foreach($data as $x)$s->execute([$x['id'],$x['label'],$x['url']??'', $x['page_slug']??'',(int)!empty($x['visible']),(int)($x['sort']??50)]);}elseif($key==='pages'){$p->exec('DELETE FROM pages');$s=$p->prepare('INSERT INTO pages(id,slug,title,eyebrow,hero_text,content,cta_title,cta_text,cta_label,cta_url,seo_title,seo_description,sort_order,visible) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($data as $i=>$x)$s->execute([$x['id'],$x['slug'],$x['title'],$x['eyebrow']??'', $x['hero_text']??'', $x['content']??'', $x['cta_title']??'', $x['cta_text']??'', $x['cta_label']??'', $x['cta_url']??'', $x['seo_title']??'', $x['seo_description']??'',(int)($x['sort_order']??$i*10),isset($x['visible'])?(int)(bool)$x['visible']:1]);}elseif($key==='projects'){$p->exec('DELETE FROM project_images');$p->exec('DELETE FROM projects');$s=$p->prepare('INSERT INTO projects(id,slug,name,location,category,status,description,featured,sort_order,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$im=$p->prepare('INSERT INTO project_images(project_id,image_url,sort_order) VALUES(?,?,?)');foreach($data as $i=>$x){$created=!empty($x['created_at'])?date('Y-m-d H:i:s',strtotime($x['created_at'])):date('Y-m-d H:i:s');$s->execute([$x['id'],$x['slug'],$x['name'],$x['location']??'', $x['category']??'', $x['status']??'', $x['description']??'',(int)!empty($x['featured']),(int)($x['sort_order']??$i*10),$created]);foreach($x['images']??[] as $n=>$url)$im->execute([$x['id'],$url,$n]);}}elseif($key==='seo'){$p->exec('DELETE FROM seo_settings');$s=$p->prepare('INSERT INTO seo_settings(page_key,title,description,keywords) VALUES(?,?,?,?)');foreach($data as $k=>$x)$s->execute([$k,$x['title']??'', $x['description']??'', $x['keywords']??'']);}elseif($key==='quotes'){$p->exec('DELETE FROM quote_submissions');$s=$p->prepare('INSERT INTO quote_submissions(name,email,phone,project_type,location,message,status,submitted_at) VALUES(?,?,?,?,?,?,?,?)');foreach($data as $x)$s->execute([$x['name']??'', $x['email']??'', $x['phone']??'', $x['project_type']??'', $x['location']??'', $x['message']??'', $x['status']??'new',!empty($x['created_at'])?date('Y-m-d H:i:s',strtotime($x['created_at'])):date('Y-m-d H:i:s')]);}else{$s=$p->prepare('INSERT INTO site_store(store_key,payload) VALUES(?,?) ON DUPLICATE KEY UPDATE payload=VALUES(payload)');$s->execute([$key,json_encode($data,JSON_UNESCAPED_SLASHES)]);}$p->commit();return true;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();error_log('DB write failed '.$key.': '.$e->getMessage());return false;}}
function default_home():array{return ['hero_eyebrow'=>'BUILT WITH PURPOSE','hero_title'=>'Craftsmanship that frames the future.','hero_text'=>'Professional framing and construction built around quality, safety, communication and dependable execution.','about_title'=>'Working together. Building it right.','about_text'=>'We bring a hands-on approach to every project, coordinating crews, schedules and details with one goal: deliver strong work our clients can count on.','contact_title'=>'Have a project in mind?','contact_text'=>'Tell us about the scope, schedule and location. We’ll get back to you to discuss the next steps.'];}function home_content():array{return array_merge(default_home(),read_json('home.json',[]));}function services():array{return read_json('services.json',[['id'=>'wood','name'=>'Wood Framing','description'=>'Structural framing for residential and commercial construction.'],['id'=>'construction','name'=>'Construction','description'=>'Reliable field execution with a focus on schedule, coordination and quality.'],['id'=>'support','name'=>'Project Support','description'=>'Experienced crews ready to support complex scopes and active jobsites.']]);}function seo(string $page='home'):array{$all=read_json('seo.json',[]);$defaults=['title'=>'Galindos Builders LLC | Framing & Construction','description'=>'Professional framing and construction services by Galindos Builders LLC.','keywords'=>'framing contractor, construction, Maryland'];return array_merge($defaults,$all[$page]??[]);}function tabs():array{$d=[['id'=>'projects','label'=>'Projects','url'=>site_url('/projects'),'visible'=>true,'sort'=>10,'page_slug'=>''],['id'=>'services','label'=>'Services','url'=>site_url('/#services'),'visible'=>true,'sort'=>20,'page_slug'=>''],['id'=>'about','label'=>'About','url'=>site_url('/#about'),'visible'=>true,'sort'=>30,'page_slug'=>''],['id'=>'contact','label'=>'Contact','url'=>site_url('/#contact'),'visible'=>true,'sort'=>40,'page_slug'=>'']];$a=read_json('tabs.json',$d);usort($a,fn($x,$y)=>($x['sort']??0)<=>($y['sort']??0));return $a;}function custom_pages():array{return read_json('pages.json',[]);}function custom_page_by_slug(string $slug):?array{foreach(custom_pages() as $p)if(($p['slug']??'')===$slug)return $p;return null;}function tab_url(array $tab):string{if(!empty($tab['page_slug']))return site_url('/page/'.rawurlencode((string)$tab['page_slug']));return (string)($tab['url']??site_url('/'));}function safe_page_html(string $html):string{$allowed='<p><br><strong><b><em><i><u><h2><h3><h4><ul><ol><li><blockquote><a><hr>';$html=strip_tags($html,$allowed);$html=preg_replace('/\s+on\w+\s*=\s*(["\']).*?\1/is','',$html);$html=preg_replace('/javascript\s*:/i','',$html);return $html;}function projects():array{return array_reverse(read_json('projects.json',[]));}function project_by_slug(string $s):?array{foreach(projects() as $p)if(($p['slug']??'')===$s)return $p;return null;}
function save_uploaded_images(array $f):array{$out=[];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($f['tmp_name']))return $out;foreach((array)$f['tmp_name'] as $i=>$tmp){if(((array)$f['error'])[$i]!==UPLOAD_ERR_OK||!is_uploaded_file($tmp)||filesize($tmp)>10*1024*1024)continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);if(!isset($allowed[$mime]))continue;$n=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(move_uploaded_file($tmp,UPLOAD_PATH.'/'.$n))$out[]=site_url('/uploads/projects/'.$n);}return $out;}function delete_project_image(string $url):void{$path=parse_url($url,PHP_URL_PATH);$file=ROOT_PATH.'/'.ltrim((string)$path,'/');if(str_starts_with(realpath(dirname($file))?:'',realpath(UPLOAD_PATH)?:UPLOAD_PATH)&&is_file($file))@unlink($file);}
